def log_event(event_name, *args, **kwargs):
    print(f'Event: {event_name}, positional: {args}, keyword: {kwargs}')

log_event('login', 'intern_01', ip='127.0.0.1', success=True)

class Employee:
    def __init__(self, name: str):
        self.name = name

class Intern(Employee):
    def __init__(self, name: str, mentor: str):
        super().__init__(name)
        self.mentor = mentor
